INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66328166', 66328166, 'analyze_legacy', 'Kementerian Dalam Negeri', 'central', 'DIREKTORAT JENDERAL BINA ADMINISTRASI KEWILAYAHAN', 'Tenaga Ahli Analisa Data Dan Sistem Informasi Kegiatan Pemutakhiran Sistem Informasi Pelaporan Gubernur Sebagai Wakil Pemerintah Pusat (SIPGWPP) & Pengembangan Sistem Informasi Pelaporan Program Prioritas Presiden', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 49450500, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Keberadaan Gubernur sebagai Wakil Pemerintah Pusat telah diatur dalam Undang-Undang Nomor 23 Tahun 2014 tentang Pemerintahan Daerah dan Peraturan Pemerintah Nomor 33 Tahun 2018 tentang Pelaksanaan Tugas dan Wewenang Gubernur sebagai Wakil Pemerintah Pusat, dimana dalam melaksanakan pembinaan dan pengawasan terhadap penyelenggaraan Urusan Pemerintahan yang menjadi kewenangan Daerah Kabupaten/Kota dan Tugas Pembantuan oleh Daerah Kabupaten/Kota, Presiden dibantu oleh Gubernur sebagai Wakil Pemerintah Pusat. Presiden melimpahkan 46 (empat puluh enam) tugas dan wewenang kepada Gubernur sebagai Wakil Pemerintah Pusat secara atributif sebagaimana diamanatkan dalam Undang-Undang nomor 23 Tahun 2014 tentang Pemerintahan Daerah. Disamping tugas dan wewenang yang bersifat atributif, Presiden melalui Menteri/ Kepala Lembaga dapat melimpahkan tugas dan wewenang yang bersifat delegatif sesuai dengan Peraturan Perundang-Undangan. Dan untuk memastikan agar Gubernur sebagai Wakil Pemerintah Pusat benar-benar menjalankan tugas dan fungsinya sebagaimana yang telah diamanatkan melalui Undang-Undang, Direktorat Jenderal Bina Administrasi Kewilayahan Kementerian Dalam Negeri pada tahun 2021 telah mendesain alat ukur berupa matriks Indikator Keberhasilan (Key Performance Indikator) dan menginisiasi pengembangan Sistem Informasi Pelaporan Gubernur Sebagai Wakil Pemerintah Pusat (SIP GWPP) sebagai media pelaporan terintegrasi berbasis teknologi informasi yang digunakan oleh Gubernur dan jajarannya untuk menginformasikan & melaporkan aktivitasnya sebagai wakil pemerintah pusat sebagaimana yang telah diamanatkan oleh Undang-Undang. Penilaian Kinerja ini diterapkan secara bertahap sejak tahun 2022. Seiring dengan pelaksanaan indikator tersebut, SIP GWPP sebagai media pelaporan juga terus dipelihara, disempurnakan & dimutakhirkan mengikuti evaluasi, masukan, dan kebutuhan yang terus berkembang. Ditahun 2026, Direktorat Jenderal Bina Administrasi Kewilayahan Kementerian Dalam Negeri menargetkan terselenggaranya 7 (Tujuh) dari 46 tugas dan wewenang Gubernur sebagai Wakil Pemerintah Pusat sesuai amanat PP Nomor 33 Tahun 2018 dan tata kelola pelaksanaan tugas sebagaimana diamanatkan dalam Peraturan Menteri Dalam Negeri Nomor 12 Tahun 2021 tentang Peraturan Pelaksanaan PP Nomor 33 Tahun 2018. Selain itu, sebagai bentuk langkah konkrit dukungan Kementerian Dalam Negeri dalam mensukseskan kegiatan pemerintah sehubungan dengan Program Prioritas Presiden, Kementerian Dalam Negeri khususnya Direktorat Jenderal Bina Administrasi Kewilayahan berinisiatif untuk Teknologi informasi merupakan salah satu hal penting dalam kelancaran kegiatan instansi pemerintah, termasuk dalam hal pengolahan, penyimpanan dan pengaksesan informasi. Sesuai dengan pasal 3 ayat 2 dalam Peraturan Menteri Dalam Negeri Tahun 2017 tentang Pedoman Presiden Nomor 39 tahun 2019 tentang Satu Data Indonesia bahwa untuk memperoleh data akurat, mutakhir, terpadu dan dapat dipertanggungjawabkan, mudah diakses dan dibagi pakaikan, maka diperlukan perbaikan tata kelola data yang dihasilkan melalui penyelenggaraan Satu Data Indonesia di lingkup Kementerian Dalam Negeri, khususnya Direktorat Jenderal Bina Administrasi Kewilayahan (Ditjen Adwil).', 'Standar teknis kegiatan Pemutakhiran Sistem Informasi Pelaporan Gubernur sebagai Wakil Pemerintah Pusat & Pengembangan Sistem Informasi Pelaporan Program Prioritas Presiden melalui Pemanfaatan Sistem Informasi yang Terintegrasi di lingkungan Kementerian Dalam Negeri adalah sebagai berikut 1. Basis Data Sebagai penyimpanan data, dapat menggunakan DBMS open source yang cepat, ringan, dan mampu menampung data dalam jumlah besar. 2. Sistem a. Aplikasi berbasis web dan dapat berjalan dengan baik di web browser. b. Menggunakan bahasa pemrograman khusus website dan mobile. c. Menggunakan CSS framework yang mengadopsi responsive design. 3. Jaringan Sistem yang dibangun harus mendukung tipe jaringan client-server yang dapat mengakomodir penggunaan secara multiuser disaat yang bersamaan. 4. Keamanan a. Autentifikasi pengguna yaitu setiap pengguna memiliki password tersendiri sehingga hanya pengguna tertentu yang dapat mengakses data. Oleh karena itu diperlukan tools untuk management user. b. Pengaturan hak akses pengguna yaitu pengaturan kewenangan masing- masing pengguna dalam menggunakan aplikasi. c. Backup/restore aplikasi dan basis data yang dilakukan oleh sistem operasi secara terjadwal. d. Mencegah masuknya pengguna lain dengan menggunakan karakter- karakter tertentu dalam pemrograman.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2674885);
