INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66332681', 66332681, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'PENGADAAN JASA KONSULTAN PENYUSUNAN BAHAN PENGEMBANGAN KEBIJAKAN DAN ANALISIS PERENCANAAN INFRASTRUKTUR HILIRISASI KEGIATAN PENGELOLAAN MANAJEMEN INTERNAL', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 83875000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1', 'A. Penyusunan Analisis Kesenjangan dan Kajian Strategis Pendukung Infrastruktur Hilirisasi i. Mengidentifikasi isu strategis dan kesenjangan (gap) antara pasokan infrastruktur eksisting dengan kebutuhan industri pengolahan/smelter di wilayah prioritas. ii. Menyusun telaah kebijakan (policy review) terhadap usulan program/kegiatan dari Direktorat teknis untuk memastikan keselarasan dengan target hilirisasi nasional. iii. Merumuskan strategi integrasi logistik dan konektivitas antarmoda guna mendukung efisiensi rantai pasok industri. (Sesuai KAK)', '1. Latar Belakang Pendidikan dan Persyaratan Umum a. Memiliki latar belakang pendidikan S1 Teknik atau keilmuan lain yang linear dengan Pembangunan dan Pendayagunaan Hilirisasi/Infrastruktur Hilirisasi. b. Memiliki pengalaman kerja profesional paling sedikit 9 (sembilan) tahun di lingkungan pemerintah maupun swasta. c. Memiliki nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran. d. Berpengalaman dengan pelaporan dan audit. e. Memiliki keterampilan interpersonal, fasilitasi kelompok, dan wawancara yang kuat. (Sesuai KAK)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2677986);
