INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66332003', 66332003, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL KEKAYAAN INTELEKTUAL', 'Pengadaan Kebutuhan Pimpinan Berupa Cetakan Kemasan Kartu Ucapan Ramadhan 1447 H pada Direktorat Jenderal Kekayaan Intelektual - Provinsi DK Jakarta TA 2026', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 49865573, 'February 2026', 'APBN - PNBP (D)', 1, 1, '7 Hari', 'Sehubungan dengan peringatan bulan suci Ramadhan 1447 H, dipandang perlu untuk menyiapkan cetak kemasan kartu ucapan Ramadhan sebagai bagian dari kebutuhan pimpinan Direktorat Jenderal Kekayaan Intelektual (DJKI) Kementerian Hukum Republik Indonesia dalam rangka menjaga dan mempererat hubungan kerja kelembagaan. Penyampaian ucapan tersebut ditujukan kepada Menteri Hukum, Wakil Menteri Hukum, dan Pimpinan Madya Unit Eselon 1 di lingkungan Kementerian Hukum Republik Indonesia sebagai bentuk penghormatan dan perhatian dalam momentum keagamaan sekaligus sebagai sarana mempererat hubungan kerja dan harmonisasi antar pimpinan. Kegiatan ini bersifat kedinasan, tidak bermuatan politik maupun kepentingan pribadi, melainkan murni dalam bentuk komunikasi institusional yang wajar dan proporsional dalam konteks hubungan kedinasan, serta tetap dilaksanakan dengan memperhatikan ketentuan peraturan perundang-undangan, norma dan etika pejabat publik, serta prinsip kepatuhan terhadap ketentuan batas undang-undang yang berlaku', '1 Desain Kartu Ucapan 15 Unit 2 Cetak Kartu Ucapan 15 Unit 3 Pembuatan Kemasan Kartu ucapan Menteri dan Wakil Menteri: 2 Unit - Box Custom Ramadhan 1447 H - Hiasan isi Box - Kurma - Tasbih - Sajadah - Sirup Premium 4 Pembuatan Kemasan Kartu Ucapan Pimti Madya : 13 Unit - Box Custom Ramadhan 1447 H - Hiasan isi Box - Kurma - Tasbih - Sajadah - Sirup Premium 5. Finishing dan pengepakan 15 Unit', 49865573, 'absurd', 'Pengadaan kemasan kartu ucapan Ramadhan untuk pimpinan disertai isi parcel seperti kurma, tasbih, sajadah, dan sirup premium bagi pejabat internal kementerian merupakan belanja seremonial/hampers yang tidak menunjukkan keterkaitan langsung dengan tugas inti layanan publik. Dalam konteks penggunaan dana publik, item ini menimbulkan kesan tidak patut dan berisiko memicu kecemburuan sosial, sehingga seluruh nilai pengadaan layak dicermati sebagai potensi pemborosan.', NULL, NULL, 4, 1, 1, 1, 1, 2678572);
